!function(){const{mount:e}=window.MCA.site;e({active:"faq",trail:[{label:"Home",href:"../index.html"},{label:"FAQ"}]}),document.getElementById("faqList").innerHTML=window.MCA.FAQ.map((e,t)=>`\n    <div class="faq-item" data-idx="${t}">\n      <button class="faq-q"><span>${e.q}</span><span class="plus">+</span></button>\n      <div class="faq-a"><div class="faq-a-inner">${e.a}</div></div>\n    </div>`).join("");const t=document.createElement("script");t.type="application/ld+json",t.textContent=JSON.stringify({"@context":"https://schema.org","@type":"FAQPage",mainEntity:window.MCA.FAQ.map(e=>({"@type":"Question",name:e.q,acceptedAnswer:{"@type":"Answer",text:e.a.replace(/<[^>]+>/g," ").replace(/\s+/g," ").trim()}}))}),document.head.appendChild(t),document.querySelectorAll(".faq-item").forEach(e=>{e.querySelector(".faq-q").addEventListener("click",()=>{const t=e.classList.contains("open");e.classList.toggle("open"),!t&&window.MCA.achievements&&window.MCA.achievements.track("faq_opened",{})})}),document.getElementById("faqSearch").addEventListener("input",e=>{const t=e.target.value.toLowerCase();document.querySelectorAll(".faq-item").forEach(e=>{const n=e.textContent.toLowerCase();e.style.display=n.includes(t)?"":"none"}),t.trim()&&window.MCA.achievements&&window.MCA.achievements.track("faq_searched",{})})}();
